package com.portfolio.fraud.controller;
import com.portfolio.fraud.dto.AuthDtos.*; import com.portfolio.fraud.dto.FraudDtos.AnalysisResponse; import com.portfolio.fraud.dto.TransactionDtos.*; import com.portfolio.fraud.entity.*; import com.portfolio.fraud.service.*; import jakarta.validation.Valid; import java.time.Instant; import java.util.*; import org.springframework.data.domain.Page; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") class AuthController {final AuthService auth;AuthController(AuthService a){auth=a;}@PostMapping("/register") AuthResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r);}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);}}
@RestController @RequestMapping("/api") class CustomerController {final TransactionService tx;final AccountService accounts;final IdempotencyService keys;CustomerController(TransactionService t,AccountService a,IdempotencyService keys){tx=t;accounts=a;this.keys=keys;}@GetMapping("/me") Map<String,String> me(@AuthenticationPrincipal User u){return Map.of("email",u.getEmail(),"role",u.getRole().name(),"fullName",u.getFullName());}@GetMapping("/accounts") List<AccountResponse> list(@AuthenticationPrincipal User u){return tx.accounts(u);}@PostMapping("/accounts") AccountResponse create(@AuthenticationPrincipal User u,@Valid @RequestBody CreateAccountRequest r){return accounts.create(u,r);}@GetMapping("/transactions") Page<TransactionResponse> history(@AuthenticationPrincipal User u,@RequestParam(required=false) TransactionType type,@RequestParam(required=false) TransactionStatus status,@RequestParam(required=false) RiskLevel risk,@RequestParam(required=false) Instant from,@RequestParam(required=false) Instant to,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return tx.history(u,type,status,risk,from,to,page,size);}@GetMapping("/transactions/{id}") TransactionResponse detail(@AuthenticationPrincipal User u,@PathVariable Long id){return tx.detail(u,id);}@GetMapping("/transactions/{id}/fraud") AnalysisResponse fraud(@AuthenticationPrincipal User u,@PathVariable Long id){return tx.fraudDetail(u,id);}@PostMapping("/transactions/transfer") TransactionResponse transfer(@AuthenticationPrincipal User u,@RequestHeader(value="Idempotency-Key",required=false) String key,@Valid @RequestBody TransferRequest r){return keys.execute(u,"transfer",key,r,()->tx.transfer(u,r));}@PostMapping("/transactions/deposit") TransactionResponse deposit(@AuthenticationPrincipal User u,@RequestHeader(value="Idempotency-Key",required=false) String key,@Valid @RequestBody MoneyRequest r){return keys.execute(u,"deposit",key,r,()->tx.deposit(u,r));}@PostMapping("/transactions/withdraw") TransactionResponse withdraw(@AuthenticationPrincipal User u,@RequestHeader(value="Idempotency-Key",required=false) String key,@Valid @RequestBody MoneyRequest r){return keys.execute(u,"withdraw",key,r,()->tx.withdrawal(u,r));}}
